<script>
export default {
  name: 'LogsLiveMetrics',
  props: {
    /** Array of log entry objects from the current result set */
    logs: { type: Array, default: () => [] },
    /** Total count from the server (may differ from logs.length due to pagination) */
    total: { type: Number, default: 0 }
  },
  computed: {
    // Aggregate stats from visible logs
    stats() {
      const s = {
        total: this.total,
        inputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        totalCost: 0,
        hasCost: false,
        errors: 0,
        avgDuration: 0,
        durationCount: 0,
        models: new Set(),
        providers: new Set(),
        users: new Set(),
      }
      for (const l of this.logs) {
        s.inputTokens += l.input_tokens || 0
        s.outputTokens += l.output_tokens || 0
        s.totalTokens += l.total_tokens || 0
        if (l.cost_cxjcoins != null) { s.totalCost += l.cost_cxjcoins; s.hasCost = true }
        if (l.error) s.errors++
        if (l.duration_ms) { s.avgDuration += l.duration_ms; s.durationCount++ }
        if (l.model) s.models.add(l.model)
        if (l.provider) s.providers.add(l.provider)
        if (l.username) s.users.add(l.username)
      }
      if (s.durationCount) s.avgDuration = s.avgDuration / s.durationCount
      return s
    },

    kpis() {
      const s = this.stats
      return [
        {
          label: 'Total Logs',
          value: this.fmtNum(s.total),
          sub: `${this.logs.length} loaded`,
          icon: 'fa-solid fa-list',
          color: 'text-primary',
          bgColor: 'bg-primary/10'
        },
        {
          label: 'Input Tokens',
          value: this.fmtNum(s.inputTokens),
          sub: 'visible page',
          icon: 'fa-solid fa-arrow-up',
          color: 'text-success',
          bgColor: 'bg-success/10'
        },
        {
          label: 'Output Tokens',
          value: this.fmtNum(s.outputTokens),
          sub: 'visible page',
          icon: 'fa-solid fa-arrow-down',
          color: 'text-warning',
          bgColor: 'bg-warning/10'
        },
        {
          label: 'Total Tokens',
          value: this.fmtNum(s.totalTokens),
          sub: 'visible page',
          icon: 'fa-solid fa-hashtag',
          color: 'text-secondary',
          bgColor: 'bg-secondary/10'
        },
        {
          label: 'Cost',
          value: s.hasCost ? '🪙 ' + this.fmtCoins(s.totalCost) : 'N/A',
          sub: 'visible page',
          icon: 'fa-solid fa-coins',
          color: 'text-fuchsia-400',
          bgColor: 'bg-fuchsia-400/10'
        },
        {
          label: 'Avg Duration',
          value: s.durationCount ? (s.avgDuration / 1000).toFixed(2) + 's' : 'N/A',
          sub: 'per call',
          icon: 'fa-solid fa-stopwatch',
          color: 'text-info',
          bgColor: 'bg-info/10'
        },
        {
          label: 'Errors',
          value: s.errors.toString(),
          sub: s.errors > 0 ? 'need attention' : 'all clear',
          icon: 'fa-solid fa-triangle-exclamation',
          color: s.errors > 0 ? 'text-error' : 'text-success',
          bgColor: s.errors > 0 ? 'bg-error/10' : 'bg-success/10'
        },
        {
          label: 'Models',
          value: s.models.size.toString(),
          sub: Array.from(s.models).slice(0, 2).join(', ') || '—',
          icon: 'fa-solid fa-microchip',
          color: 'text-accent',
          bgColor: 'bg-accent/10'
        },
      ]
    }
  },
  methods: {
    fmtNum(n) {
      if (!n) return '0'
      if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M'
      if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K'
      return n.toString()
    },
    fmtCoins(c) {
      if (c >= 1_000_000) return (c / 1_000_000).toFixed(2) + 'M'
      if (c >= 1_000) return (c / 1_000).toFixed(2) + 'K'
      return Number(c).toFixed(2)
    }
  }
}
</script>
