          <button
            v-for="p in visiblePages"
            :key="p"
            class="join-item btn btn-xs"
            :class="{ 'btn-active btn-primary': p === page }"
            @click="$emit('page', p)"
          >{{ p }}</button>
          <button class="join-item btn btn-xs" :disabled="!hasMore" @click="$emit('page', page + 1)">
            <i class="fa-solid fa-chevron-right"></i>
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'LogsTable',
  emits: ['select', 'page', 'page-size'],
  props: {
    logs: { type: Array, default: () => [] },
    total: { type: Number, default: 0 },
    page: { type: Number, default: 1 },
    pageSize: { type: Number, default: 50 },
    hasMore: { type: Boolean, default: false },
    loading: { type: Boolean, default: false },
  },
  data() {
    return { localPageSize: this.pageSize }
  },
  computed: {
    totalPages() {
      return Math.ceil(this.total / this.localPageSize) || 1
    },
    /** Show at most 7 page buttons around current page */
    visiblePages() {
      const total = this.totalPages
      const cur = this.page
      const delta = 3
      const pages = []
      for (let i = Math.max(1, cur - delta); i <= Math.min(total, cur + delta); i++) {
        pages.push(i)
      }
      return pages
    }
  },
  methods: {
    formatTs(ts) {
      if (!ts) return '—'
      try {
        return new Date(ts).toLocaleString('en-US', {
          month: '2-digit', day: '2-digit',
          hour: '2-digit', minute: '2-digit', second: '2-digit'
        })
      } catch { return ts }
    },
    fmtNum(n) {
      if (!n) return '0'
      if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M'
      if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K'
      return n.toString()
    },
    onPageSizeChange() {
      this.$emit('page-size', this.localPageSize)
    }
  }
}
</script>
