    },
    topProviders() {
      return this.topN(this.logs, 'provider', 'total_tokens', 5)
    },
    topProjects() {
      return this.topN(this.logs, 'project_name', 'total_tokens', 5)
    }
  },
  methods: {
    /** Aggregate by groupKey, sum valueKey, return top N with percentages */
    topN(items, groupKey, valueKey, n) {
      const map = {}
      for (const item of items) {
        const k = item[groupKey] || '(unknown)'
        map[k] = (map[k] || 0) + (item[valueKey] || 1)
      }
      const sorted = Object.entries(map)
        .sort((a, b) => b[1] - a[1])
        .slice(0, n)
      const maxVal = sorted[0]?.[1] || 1
      return sorted.map(([name, val]) => ({
        name,
        val,
        pct: Math.round((val / maxVal) * 100)
      }))
    }
  }
}
</script>
