```js src/api/api.js
import { CodxJuniorConnection } from './connection'
import { SocketManager } from './socket'

const _inflightRequests = new Map()

function _requestKey(method, url, data) {
  const body = data !== undefined ? JSON.stringify(data) : ''
  return `${method.toUpperCase()}:${url}:${body}`
}

function _dedupedRequest(method, url, data, requestFn) {
  const key = _requestKey(method, url, data)
  if (_inflightRequests.has(key)) return _inflightRequests.get(key)
  const promise = requestFn().finally(() => _inflightRequests.delete(key))
  _inflightRequests.set(key, promise)
  return promise
}

const initializeAPI = ({ project, user } = {}) => {
  const API = {
    sid: "",
    connection: null,
    _socketManager: null,
    _socketEventHandlers: [],
    _user: user,

    get user() { return API._user },
    set user(user) { API._user = user; API.initConnection() },

    _activeProject: project,
    get activeProject() { return this._activeProject },
    set activeProject(value) { this._activeProject = value; API.initConnection() },

    set interceptors(value) { Object.assign(this.connection.interceptors, value) },

    initConnection() {
      API.connection = new CodxJuniorConnection({ settings: API.activeProject, user: API.user })
    },

    // ─── HTTP helpers ────────────────────────────────────────────────────────
    get(url) {
      return _dedupedRequest('GET', API.connection.prepareUrl(url), undefined, () => API.connection.get(url))
    },
    del(url) {
      return _dedupedRequest('DEL', API.connection.prepareUrl(url), undefined, () => API.connection.del(url))
    },
    post(url, data) {
      return _dedupedRequest('POST', API.connection.prepareUrl(url), data, () => API.connection.post(url, data))
    },
    put(url, data) {
      return _dedupedRequest('PUT', API.connection.prepareUrl(url), data, () => API.connection.put(url, data))
    },
    delete(url) {
      return _dedupedRequest('DELETE', API.connection.prepareUrl(url), undefined, () => API.connection.delete(url))
    },

    // ─── Socket management ───────────────────────────────────────────────────
    initSocket({ onConnect, onDisconnect, onEvent } = {}) {
      if (API._socketManager) API._socketManager.disconnect()
      API._socketManager = new SocketManager({
        onConnect(socketId) { API.sid = socketId; if (typeof onConnect === 'function') onConnect(socketId) },
        onDisconnect() { API.sid = ''; if (typeof onDisconnect === 'function') onDisconnect() },
        onEvent(payload) { if (typeof onEvent === 'function') onEvent(payload) }
      })
      API._socketManager.connect()
      return API._socketManager
    },
    get socket() { return API._socketManager },
    disconnectSocket() {
      if (API._socketManager) { API._socketManager.disconnect(); API._socketManager = null }
    },

    // ─── Domain helpers ──────────────────────────────────────────────────────
    oauth: {
      async getOAuthLoginUrl(provider) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${provider}`)
        return await API.get(`/api/users/oauth-login-url/${provider}?redirect_uri=${redirect_uri}`)
      },
      async oauthLogin({ oauth_provider, code, state }) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${oauth_provider}`)
        const data = await API.post('/api/users/oauth-login', { oauth_provider, code, state, redirect_uri })
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      }
    },

    users: {
      async list() { API.userNetwork = await API.get('/api/users'); return API.userNetwork },
      async login(user) {
        if (!user) {
          try { user = API.user = JSON.parse(localStorage.getItem("CODX_USER")); API.initConnection() } catch {}
          if (!user) return null
        }
        const data = await API.post('/api/users/login', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      },
      async save(user) {
        const data = await API.put('/api/users', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        return data
      },
      async logout() { API.user = null; API.activeProject = {}; localStorage.removeItem("CODX_USER") },
      async refreshInfo() {
        const data = await API.get('/api/users/me/refresh')
        if (data && API.user) {
          API.user = {
            ...API.user,
            token_usage_today: data.token_usage_today,
            token_limits_today: data.token_limits_today,
            token_limit_rules: data.token_limit_rules,
            token_limit_requests: data.token_limit_requests,
          }
        }
        return data
      }
    },

    apps: {
      async list() { return await API.get('/api/apps') },
      async run(appName) { return await API.get(`/api/apps/run?app=${appName}`) },
      async runScript(script) { return await API.post('/api/run/script', { script }) }
    },

    async project(projectOrId) {
      if (!projectOrId.codx_path) {
        const existingProject = API.allProjects.find(p => p.id === projectOrId || p.project_name === projectOrId)
        if (!existingProject) throw new Error("Invalid projectOrId: " + JSON.stringify(projectOrId))
        projectOrId = existingProject
      }
      if (projectOrId.codx_path === API.settings.codx_path) return API
      return initializeAPI({ ...API, project: projectOrId })
