      create(projectPath) { return API.post('/api/projects?project_path=' + encodeURIComponent(projectPath), {}) },
      delete() { localStorage.setItem("API_SETTINGS", ""); API.del('/api/projects'); API.activeProject = null },
      async readme() { return await API.get('/api/projects/readme') },
      async watch(watching) { const settings = await API.settings.read(); settings.watching = watching; API.settings.save(settings) },
      test() { return API.get('/api/project/script/test') },
      loadIssue(url) { return API.get('/api/github/issues/read?issue_url=' + encodeURIComponent(url)) },
      ai: {
        models: {
