      save(view) { return API.post('/api/views', view) },
      delete(name) { return API.delete(`/api/views/${encodeURIComponent(name)}`) },
      rename(oldName, newName) { return API.put(`/api/views/${encodeURIComponent(oldName)}`, { name: newName }) }
    },

    repo: {
