      changes({ from_branch, to_branch }) {
        return API.get(`/api/projects/repo/changes?from_branch=${from_branch}&to_branch=${to_branch}`)
      }
    },

    settings: {
      async read() {
        const data = await API.get('/api/settings')
        API.activeProject = { ...API.activeProject || {}, ...data }
        if (API.activeProject) localStorage.setItem("API_SETTINGS", JSON.stringify(data))
        return data
      },
      async save(settings) {
        await API.put('/api/settings?', settings || { ...API.activeProject, $api: null, $state: null })
        return API.settings.read()
      },
      global: {
        async read() { const data = await API.get('/api/global/settings'); API.globalSettings = data; return data },
        async write(settings) { await API.post('/api/global/settings', settings); return API.settings.global.read() },
        plugins: {
          async list() { return await API.get('/api/plugins') },
          async add(plugin) { return await API.post('/api/plugins', plugin) },
          async remove(pluginName) { return await API.delete(`/api/plugins/${pluginName}`) },
          async loadFromFile(fileName) { return await API.get(`/api/plugins/load_from_file?file_path=${encodeURIComponent(fileName)}`) }
        }
      }
    },

    knowledge: {
      status() { return API.get('/api/knowledge/status') },
