            })
          }
        }
      }
    },

    // ─── AI Raw Logs ─────────────────────────────────────────────────────────
    // Backed by RawLogReader / RawAILogger JSONL files.
    // Log entry fields: log_id, timestamp, direction, username, project,
    //   session_id, model, provider, base_url, tags, duration_seconds,
    //   payload_preview, payload (full only)
    logs: {
      // System/server logs (legacy)
      async read(logName, size) { return API.get(`/api/logs/${logName}?log_size=${size}`) },
      async list() { return API.get('/api/logs') },

      ai: {
        /**
         * Recent logs for the authenticated user.
         * Returns { username, recent_logs: LogEntry[], count }
         */
        me(limit = 10) {
          return API.get(`/api/logs/me?limit=${limit}`)
        },

        /**
         * Paginated log list for the authenticated user.
         * Filters: startDate, endDate, project (mapped to `project` in backend),
         *   model, provider, direction, sessionId, page, pageSize
         * Returns LogListResponse { items, total, page, page_size, has_more }
         */
        list({ startDate, endDate, project, model, provider, direction, sessionId, page = 1, pageSize = 50 } = {}) {
          const qs = _buildLogsQS({ startDate, endDate, project, model, provider, direction, sessionId, page, pageSize })
          return API.get(`/api/logs/list${qs}`)
        },

        /**
         * Full log entry (with payload) for the authenticated user.
         * log_id format: <YYYY-MM-DD>:<line_index>
         */
        get(logId) {
          return API.get(`/api/logs/${encodeURIComponent(logId)}`)
        },

        admin: {
          /**
           * Paginated log list across ALL users (admin only).
           * Filters: startDate, endDate, username, project, model,
           *   provider, direction, sessionId, page, pageSize
           */
          list({ startDate, endDate, username, project, model, provider, direction, sessionId, page = 1, pageSize = 50 } = {}) {
            const qs = _buildLogsQS({ startDate, endDate, username, project, model, provider, direction, sessionId, page, pageSize })
            return API.get(`/api/logs/admin/list${qs}`)
          },

          /** Full log entry (with payload) for any user (admin only). */
          get(logId) {
            return API.get(`/api/logs/admin/${encodeURIComponent(logId)}`)
          },

          /** Delete a single log entry by log_id (admin only). */
          delete(logId) {
            return API.delete(`/api/logs/admin/${encodeURIComponent(logId)}`)
          },

          /**
           * Bulk delete logs matching filters (admin only).
           * At least one filter is required by the backend.
           * Body maps to PurgeRequest: start_date, end_date, username, project, model, provider
           */
          purge({ startDate, endDate, username, project, model, provider } = {}) {
            return API.post('/api/logs/admin/purge', {
              start_date: startDate || null,
              end_date: endDate || null,
              username: username || null,
              project: project || null,
              model: model || null,
              provider: provider || null,
            })
          }
        }
      }
    },

    files: {
      list(path) { return API.get(`/api/files?path=${path}`) },
      read(path) { return API.get(`/api/files/read?path=${path}`) },
      diff({ path, content }) { return API.post(`/api/files/diff`, { path, content }) },
      search(search) { return API.get(`/api/files/find?search=${search}`) },
      write(source, page_content) { return API.post(`/api/files/write?path=${source}`, { page_content, metadata: { source } }) }
    },

    screen: {
      display: null,
      async setScreenResolution(resolution) { await API.post('/api/screen', { resolution }); return API.screen.getScreenResolution() },
      async getScreenResolution() { const display = await API.get('/api/screen'); API.screen.display = display; return API.screen.display }
    },

    async restart() {
      await API.post("/api/restart")
      let waitTime = 3
      return new Promise((ok, ko) => {
        const ix = setInterval(async () => {
          if (--waitTime) {
            try { await API.init(); clearInterval(ix); ok() } catch {}
          } else { clearInterval(ix); ko() }
        }, 5000)
      })
    },

    get permissions() {
      const permissions = API.activeProject?.permissions || []
      const isAdmin = API.user?.role === 'admin'
      const isProjectAdmin = permissions.includes("admin")
      return { isAdmin, isProjectAdmin }
    },

    async onUserLogin() {
      API.allProjects = []
      API.activeProject = null
      await Promise.all([API.screen.getScreenResolution(), API.settings.global.read(), API.users.list()])
    },

    async setActiveProject({ project_id }) {
      if (project_id !== API.activeProject?.project_id) {
        API.activeProject = API.allProjects?.find(p => p.project_id === project_id)
        await API.settings.read()
      }
      return API
    }
  }

  API.initConnection()
  return API
}

// ─── Query string builders ─────────────────────────────────────────────────────

/** Generic QS builder with camelCase → snake_case mapping */
function _buildQS(params) {
  const keyMap = {
    startDate: 'start_date', endDate: 'end_date',
    username: 'username', projectName: 'project_name',
    projectId: 'project_id', model: 'model',
  }
  const parts = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${keyMap[k] || k}=${encodeURIComponent(v)}`)
  return parts.length ? `?${parts.join('&')}` : ''
}

/**
 * QS builder for AI log endpoints.
 * Backend field names match RawLogReader / RawAILogger:
 *   project (not project_name), session_id, direction, provider, model
 */
function _buildLogsQS(params) {
  const keyMap = {
    startDate: 'start_date',
    endDate: 'end_date',
    username: 'username',
    project: 'project',       // RawAILogger stores "project", not "project_name"
    model: 'model',
    provider: 'provider',
    direction: 'direction',   // "request" | "response"
    sessionId: 'session_id',
    page: 'page',
    pageSize: 'page_size',
  }
  const parts = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${keyMap[k] || k}=${encodeURIComponent(v)}`)
  return parts.length ? `?${parts.join('&')}` : ''
}

export const API = initializeAPI()
