            <i class="fa-solid fa-chevron-left"></i>
          </button>
          <button
            v-for="p in visiblePages"
            :key="p"
            class="join-item btn btn-xs"
            :class="{ 'btn-active btn-primary': p === page }"
            @click="$emit('page', p)"
          >{{ p }}</button>
          <button class="join-item btn btn-xs" :disabled="!hasMore" @click="$emit('page', page + 1)">
