<script>
export default {
  name: 'LogEntryDetail',
  emits: ['close'],
  props: {
    entry: { type: Object, default: null },
    loading: { type: Boolean, default: false }
  },
  data() {
    return { activeTab: 'messages' }
  },
  computed: {
    // Request payload has: { messages: [...], kwargs: {...} }
    requestMessages() {
      return this.entry?.payload?.messages || []
    },
    // Response payload has: { content: "...", finish_reason: "...", tool_calls: {} }
    responseContent() {
      return this.entry?.payload?.content || null
    },
    toolCalls() {
      const tc = this.entry?.payload?.tool_calls
      return tc && Object.keys(tc).length ? tc : null
    },
    finishReason() {
      return this.entry?.payload?.finish_reason || null
    },
    visibleTabs() {
      const tabs = []
      const isRequest = this.entry?.direction === 'request'
      const isResponse = this.entry?.direction === 'response'
      if (isRequest) tabs.push({ key: 'messages', label: 'Messages', icon: 'fa-solid fa-comment-dots' })
      if (isResponse) tabs.push({ key: 'content', label: 'Content', icon: 'fa-solid fa-reply' })
      if (this.toolCalls) tabs.push({ key: 'tools', label: 'Tool Calls', icon: 'fa-solid fa-wrench' })
      tabs.push({ key: 'raw', label: 'Raw', icon: 'fa-solid fa-code' })
      // Default to first tab
      if (!tabs.find(t => t.key === this.activeTab) && tabs.length) {
        this.$nextTick(() => { this.activeTab = tabs[0].key })
      }
      return tabs
    }
  },
  methods: {
    roleColor(role) {
      const map = { user: 'badge-primary', assistant: 'badge-secondary', system: 'badge-ghost', tool: 'badge-warning' }
      return map[role] || 'badge-ghost'
    },
    /** Safely extract message content (string or content array) */
    msgContent(msg) {
      if (typeof msg.content === 'string') return msg.content
      if (Array.isArray(msg.content)) return msg.content.map(c => c.text || JSON.stringify(c)).join('\n')
      return JSON.stringify(msg.content, null, 2)
    },
    formatJson(obj) {
      try { return JSON.stringify(obj, null, 2) } catch { return String(obj) }
    }
  },
  watch: {
    // Reset to first valid tab when entry changes
    entry(val) {
      if (!val) return
      const first = val.direction === 'request' ? 'messages' : 'content'
      this.activeTab = first
    }
  }
}
</script>
