<script>
export default {
  name: 'LogsAnalyzerDashboard',
  data() {
    const today = new Date().toISOString().split('T')[0]
    const sevenDaysAgo = new Date(Date.now() - 7 * 86400_000).toISOString().split('T')[0]
    return {
      loading: false,
      detailLoading: false,
      error: null,
      isAdminView: false,
      viewMode: 'table', // 'table' | 'analytics' | 'both'
      logs: [],
      total: 0,
      page: 1,
      pageSize: 50,
      hasMore: false,
      selectedLog: null,
      detailEntry: null,
      autoRefreshTimer: null,
      filters: {
        startDate: sevenDaysAgo,
        endDate: today,
        direction: '',      // 'request' | 'response' | ''
        model: '',
        provider: '',
        sessionId: '',
        tags: '',
        username: '',       // admin only
        project: '',        // maps to "project" field in RawAILogger
        autoRefresh: null,
      }
    }
  },

  computed: {
    /** Unique models from current page for filter dropdown */
    availableModels() {
      return [...new Set(this.logs.map(l => l.model).filter(Boolean))].sort()
    },
    /** Unique providers from current page for filter dropdown */
    availableProviders() {
      return [...new Set(this.logs.map(l => l.provider).filter(Boolean))].sort()
    }
  },

  watch: {
    'filters.autoRefresh'(val) { this.setupAutoRefresh(val) }
  },

  methods: {
    toggleAdminView() {
      this.isAdminView = !this.isAdminView
      this.page = 1
      this.loadLogs()
    },

    onFilterChange() { this.page = 1; this.loadLogs() },

    clearFilters() {
      const today = new Date().toISOString().split('T')[0]
      const sevenDaysAgo = new Date(Date.now() - 7 * 86400_000).toISOString().split('T')[0]
      this.filters = {
        startDate: sevenDaysAgo, endDate: today,
        direction: '', model: '', provider: '', sessionId: '',
        tags: '', username: '', project: '',
        autoRefresh: this.filters.autoRefresh,
      }
      this.page = 1
      this.loadLogs()
    },

    goToPage(p) { this.page = p; this.loadLogs() },
    onPageSizeChange(size) { this.pageSize = size; this.page = 1; this.loadLogs() },

    setupAutoRefresh(intervalSecs) {
      if (this.autoRefreshTimer) { clearInterval(this.autoRefreshTimer); this.autoRefreshTimer = null }
      if (!intervalSecs) return
      this.autoRefreshTimer = setInterval(() => this.loadLogs(), intervalSecs * 1000)
    },

    /** Build params aligned with RawLogReader.read_records / _buildLogsQS */
    buildParams() {
      const f = this.filters
      return {
        startDate: f.startDate,
        endDate: f.endDate,
        direction: f.direction || undefined,
        model: f.model || undefined,
        provider: f.provider || undefined,
        sessionId: f.sessionId || undefined,  // → session_id
        project: f.project || undefined,       // → project (not project_name)
        page: this.page,
        pageSize: this.pageSize,
      }
    },

    async loadLogs() {
      this.loading = true
      this.error = null
      try {
        const params = this.buildParams()
        let result

        if (this.isAdminView && this.$storex.users.isAdmin) {
          result = await this.$project.$api.logs.ai.admin.list({
            ...params,
            username: this.filters.username || undefined,
          })
        } else {
          result = await this.$project.$api.logs.ai.list(params)
        }

        // Backend returns LogListResponse: { items, total, page, page_size, has_more }
        this.logs = result?.items || []
        this.total = result?.total || 0
        this.hasMore = result?.has_more || false
      } catch (err) {
        console.error('Failed to load logs:', err)
        this.error = 'Failed to load log entries. Please try again.'
      } finally {
        this.loading = false
      }
    },

    async openDetail(log) {
      this.selectedLog = log
      this.detailEntry = log   // show immediately with preview data
      this.detailLoading = true
      try {
        // Fetch full entry including payload (request messages or response content)
        const full = this.isAdminView && this.$storex.users.isAdmin
          ? await this.$project.$api.logs.ai.admin.get(log.log_id)
          : await this.$project.$api.logs.ai.get(log.log_id)
        this.detailEntry = full
      } catch (err) {
        console.error('Failed to load log detail:', err)
        // Keep showing the preview entry
      } finally {
        this.detailLoading = false
      }
    },
  },

  mounted() { this.loadLogs() },
  beforeUnmount() { if (this.autoRefreshTimer) clearInterval(this.autoRefreshTimer) }
}
</script>
